from pathlib import Path
import json, base64, html
ROOT=Path(__file__).parent
meta=json.loads((ROOT/'photo_assets/metadata.json').read_text())
imgs={}
for f in sorted((ROOT/'photo_assets').rglob('*.png')):
    rel=f.relative_to(ROOT/'photo_assets').as_posix()
    imgs[rel]='data:image/png;base64,'+base64.b64encode(f.read_bytes()).decode('ascii')

def dial(name,desc,scale=2.0):
    d=meta['dials'][name]
    radius=d['cropRadius']*2
    visual=int(d['nominalDiameter']*scale)
    pad=min(35,int(visual*.18))
    return f'''<py-dial role="slider" tabindex="0" data-name="{name}" data-size="{visual}" style="--size:{visual}px;--hit:{visual+pad*2}px" aria-label="{html.escape(desc)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="50"><img class="full-photo" src="{imgs[d['dial']]}" draggable="false"><div class="layered-photo"><img class="ring-photo" src="{imgs[d['ring']]}" draggable="false"><img class="cap-photo" src="{imgs[d['cap']]}" draggable="false"></div></py-dial>'''
def box(title,content,extra='',cls=''):
    return f'<article class="tile {cls}"><header>{title}</header><div class="visual">{content}</div><footer>{extra}</footer><i class="screw screw1"></i><i class="screw screw2"></i></article>'
def block(name,width=None,cls=''):
    d=meta['modules'][name];w=width or d['size'][0]
    return f'<py-photo data-source="{name}" class="{cls}" tabindex="0" role="button" aria-label="{name}" style="--photo-width:{w}px"><img src="{imgs[d["image"]]}" draggable="false"></py-photo>'

dialset=[('xl-hero','XL — HERO  ·  Ø64',2.05),('l-standard','L — STANDARD  ·  Ø48',2),('m-compact','M — COMPACT  ·  Ø36',2),('s-trim','S — TRIM  ·  Ø24',2),('micro','MICRO  ·  Ø18',2),('nano','NANO  ·  Ø14',2)]
alt=[('l-brushed-cap','L · Brushed metal',1.9),('l-dark-cap','L · Soft black',1.9),('m-knurled-cap','M · Knurled',2.15),('m-scalloped-cap','M · Scalloped',2.15),('encoder-led','Encoder LED',1.85),('macro-morph','Macro / Morph',1.55),('rotary-selector','Selector',1.85)]
primary_cards=''.join(box(d, dial(n,d,s), 'Mueve con mouse · flechas · doble clic', 'dial-tile') for n,d,s in dialset)
alt_cards=''.join(box(d, dial(n,d,s), 'Recurso original de la biblioteca aprobada','dial-tile') for n,d,s in alt)
fader=[('fader-vertical-long','VERTICAL · 80px',65),('fader-vertical-compact','VERTICAL · 56px',53),('fader-vertical-mini','VERTICAL · 40px',48),('slider-horizontal','HORIZONTAL · 96px',180),('slider-horizontal-compact','HORIZONTAL · 72px',132),('slider-horizontal-trim','TRIM · 48px',125)]
fader_cards=''.join(box(d,block(n,w), 'Foto de referencia original','fader-tile') for n,d,w in fader)
buttons=[('switch-low-profile-on','SWITCH RECTANGULAR'),('toggle-mini','MINI TOGGLE'),('switch-3-position','3 POSITION'),('toggle-pill','ON/OFF'),('button-square-on','BUTTON SQUARE'),('button-round-on','ROUND ILLUMINATED'),('button-utility','UTILITY'),('button-icon','ICON'),('rocker-2-pos','ROCKER 2 POS'),('toggle-3-pos','TOGGLE 3 POS'),('capacitive-preset','CAPACITIVE / GLASS'),('step-sequencer','STEP BUTTON FAMILY')]
button_cards=''.join(box(d,block(n), 'Clic para alternar estado','button-tile') for n,d in buttons)
screens=[('oled-preset-strip','OLED / PRESET STRIP'),('dropdown-preview','DROPDOWN'),('vu-analog','VU METER / BLACK'),('vu-amber-compact','VU METER / AMBER'),('meter-dual-led','STEREO LED METER'),('scope-spectrum','SPECTRUM OLED'),('scope-oscilloscope','OSCILLOSCOPE'),('scope-morph','MORPH WAVES'),('status-oled-mini','MINI OLED'),('led-bar-vertical','VERTICAL METER'),('led-bar-horizontal','HORIZONTAL METER'),('value-chip','NUMERIC CHIP')]
screen_cards=''.join(box(d,block(n), 'Contenido de muestra · textura aprobada','screen-tile') for n,d in screens)
others=[('xy-performance','XY / PERFORMANCE'),('adsr-envelope','ADSR DISPLAY'),('lfo-wave-selector','LFO SHAPES'),('modulation-matrix','MODULATION MATRIX'),('navigation-tabs','MODULE TABS'),('progress-red','PROGRESS BAR'),('module-header','MODULE HEADER'),('icon-button-set','ICON SET'),('status-lamps','STATUS LAMPS')]
other_cards=''.join(box(d,block(n), 'Elemento compuesto original','screen-tile') for n,d in others)

css=r'''
*{box-sizing:border-box}html{background:#050606;color:#e5e5e6}body{margin:0;font-family:Inter,'Segoe UI',Arial,sans-serif;background:radial-gradient(ellipse at top,#25272a 0,#121416 23%,#08090a 75%);color:#e7e8ea;letter-spacing:.01em}
.app{max-width:1700px;margin:auto;padding:29px 34px 80px;overflow:hidden}
.topbar{display:flex;gap:25px;align-items:center;border-bottom:1px solid #622021;padding:0 0 20px;margin-bottom:24px}.brand{font-family:Arial,sans-serif;font-size:29px;letter-spacing:3.3px;font-weight:600}.brand span{color:#f03935}.subtitle{font-size:15px;letter-spacing:3px;color:#aeb0b3;font-weight:600}.right{margin-left:auto;color:#9d9d9e;font:11px/1.4 'Segoe UI',sans-serif;text-align:right}
.status{font-size:11px;color:#c9cccc;margin:0 0 23px;max-width:1000px;line-height:1.7}.status b{color:#ff7772}
.section{margin:25px 0 11px;font-size:13px;font-weight:700;letter-spacing:2px;color:#f0f0f0;display:flex;align-items:center;gap:18px}.section:after{content:'';height:1px;background:linear-gradient(90deg,#6b1716,transparent);flex:1}
.tiles{display:grid;gap:11px;grid-template-columns:repeat(auto-fit,minmax(205px,1fr));}.tiles.dials{grid-template-columns:repeat(6,minmax(0,1fr));}.tiles.caps{grid-template-columns:repeat(7,minmax(0,1fr));}.tiles.control{grid-template-columns:repeat(6,minmax(0,1fr));}.tiles.buttons{grid-template-columns:repeat(4,minmax(0,1fr));}.tiles.displays{grid-template-columns:repeat(4,minmax(0,1fr));}
.tile{position:relative;background:linear-gradient(155deg,#1d1f20 0%,#0f1011 55%,#111314 95%);box-shadow:inset 0 1px 0 #616365b3,inset 1px 0 0 #4e505077,inset 0 -9px 20px #000a,0 10px 20px #0008;border:1px solid #424547;border-radius:10px;min-height:210px;padding:15px 13px 12px;display:flex;flex-direction:column;justify-content:space-between;overflow:hidden;isolation:isolate}
.tile:before{content:'';pointer-events:none;position:absolute;inset:2px;border:1px solid #ffffff09;border-radius:7px}
.tile>header{font-size:12px;letter-spacing:1px;color:#e3e3e4;font-weight:700;line-height:1.35;min-height:29px;text-align:left}
.tile>.visual{flex:1;display:flex;align-items:center;justify-content:center;min-height:85px;position:relative;overflow:visible}
.tile>footer{border-top:1px solid #ffffff12;padding-top:8px;font-size:10px;color:#999a9b;min-height:20px;text-align:center}
.screw{position:absolute;bottom:13px;width:9px;height:9px;border-radius:50%;background:radial-gradient(circle at 34% 22%,#a6aaaf,#3c3f41 44%,#080909 76%);border:1px solid #0e1010;box-shadow:0 1px 2px #000;pointer-events:none}.screw1{left:7px}.screw2{right:7px}
py-dial{display:block;position:relative;width:var(--hit);height:calc(var(--size) + 24px);outline:none;cursor:ns-resize;user-select:none;touch-action:none}.full-photo,.layered-photo{position:absolute;top:calc((var(--hit) - var(--size))/2);left:calc((var(--hit) - var(--size))/2);width:var(--size);height:var(--size);pointer-events:none}.full-photo,.layered-photo>img{display:block;object-fit:contain;width:100%;height:100%}.layered-photo{display:none}.layered-photo>img{position:absolute;inset:0}.layered-photo>.cap-photo{transform-origin:50% 50%;transform:rotate(var(--angle,0deg))}.dial-interactive .full-photo{display:none}.dial-interactive .layered-photo{display:block}
py-dial:focus-visible{outline:1px solid #ff5049;border-radius:12px;outline-offset:2px}py-dial[aria-valuenow]:after{content:attr(aria-valuenow) '%';position:absolute;bottom:-1px;left:0;right:0;text-align:center;color:#868a8d;font:9px/1 monospace;letter-spacing:1px;opacity:0;transition:.2s}py-dial:hover:after,py-dial:focus:after{opacity:1}
py-photo{display:flex;align-items:center;justify-content:center;max-width:100%;cursor:pointer;position:relative;padding:3px;outline:none;border-radius:5px;filter:drop-shadow(0 5px 4px #0005)}py-photo img{display:block;max-width:100%;height:auto;width:min(var(--photo-width),100%);pointer-events:none;object-fit:contain}py-photo:focus-visible{outline:1px solid #ff5a57}py-photo.on{filter:drop-shadow(0 0 7px #e12a2866) brightness(1.13)}py-photo.off{filter:brightness(.7)}
.dial-tile{min-height:205px}.fader-tile{min-height:240px}.fader-tile .visual{min-height:165px}.button-tile{min-height:175px}.button-tile .visual{min-height:98px}.screen-tile{min-height:195px}.screen-tile .visual{min-height:116px}
.notice{font-size:11px;line-height:1.6;color:#babdc0;margin:25px 0;background:#0d1011;border-left:2px solid #b03531;padding:12px 16px}
@media(max-width:1350px){.tiles.dials,.tiles.caps{grid-template-columns:repeat(4,minmax(0,1fr))}.tiles.control{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:800px){.app{padding:15px}.tiles,.tiles.dials,.tiles.caps,.tiles.control,.tiles.buttons,.tiles.displays{grid-template-columns:repeat(2,minmax(0,1fr))}.topbar{flex-wrap:wrap}.brand{font-size:22px}.right{margin:0}}
'''
js=r'''
customElements.define('py-dial',class extends HTMLElement{connectedCallback(){this.v=.5;this.setAttribute('aria-valuenow',50);let down=false,startY=0,startV=0;const set=(v)=>{this.v=Math.max(0,Math.min(1,v));this.classList.add('dial-interactive');this.style.setProperty('--angle',Math.round((this.v-.5)*270)+'deg');this.setAttribute('aria-valuenow',Math.round(this.v*100));this.dispatchEvent(new CustomEvent('input',{detail:{value:this.v},bubbles:true}));};this.addEventListener('pointerdown',e=>{e.preventDefault();down=true;startY=e.clientY;startV=this.v;this.setPointerCapture(e.pointerId);this.classList.add('dial-interactive')});this.addEventListener('pointermove',e=>{if(down)set(startV+(startY-e.clientY)/170)});this.addEventListener('pointerup',()=>down=false);this.addEventListener('pointercancel',()=>down=false);this.addEventListener('dblclick',()=>set(.5));this.addEventListener('wheel',e=>{e.preventDefault();set(this.v-(e.deltaY/1400))},{passive:false});this.addEventListener('keydown',e=>{if(e.key==='ArrowUp'||e.key==='ArrowRight'){e.preventDefault();set(this.v+.02)}if(e.key==='ArrowDown'||e.key==='ArrowLeft'){e.preventDefault();set(this.v-.02)}if(e.key==='Home')set(0);if(e.key==='End')set(1)})}});
customElements.define('py-photo',class extends HTMLElement{connectedCallback(){this.classList.add('on');let change=()=>{this.classList.toggle('on');this.classList.toggle('off');this.setAttribute('aria-pressed',this.classList.contains('on'))};this.addEventListener('click',change);this.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();change()}})}});
'''
page=f'''<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Prophec-Y — Biblioteca fotográfica recuperada</title><style>{css}</style></head><body><main class="app"><div class="topbar"><div class="brand">PROPHEC-<span>Y</span></div><div class="subtitle">UI COMPONENT LIBRARY · FIDELITY RESTORATION</div><div class="right">DERIVED DIRECTLY FROM APPROVED CONCEPT BOARDS<br>REV. A — VISUAL REVIEW</div></div><p class="status">Componentes recortados de las <b>tres láminas aprobadas</b>, sin rediseñarlos como círculos genéricos. Interactúa con las perillas. <b>La fidelidad de estos recortes en su estado de referencia no implica que todas las transiciones y estados estén terminados en JUCE.</b></p><div class="section">01 / FAMILIA ORIGINAL DE DIALES</div><div class="tiles dials">{primary_cards}</div><div class="section">02 / CAPS, ENCODERS Y SELECTORES</div><div class="tiles caps">{alt_cards}</div><div class="section">03 / FADERS Y SLIDERS</div><div class="tiles control">{fader_cards}</div><div class="section">04 / SWITCHES, BOTONES Y PASOS</div><div class="tiles buttons">{button_cards}</div><div class="section">05 / DISPLAYS Y MEDIDORES</div><div class="tiles displays">{screen_cards}</div><div class="section">06 / MÓDULOS COMPUESTOS</div><div class="tiles displays">{other_cards}</div><p class="notice"><b>Estado técnico:</b> esta es una galería web de recursos fotográficos obtenidos de la fuente aprobada (no una captura JUCE). No representa aún los estados dinámicos finales. Los assets transparentes, sus metadatos de procedencia y el script de extracción están incluidos en el paquete fuente. No se ha modificado el editor de producción.</p></main><script>{js}</script></body></html>'''
output=ROOT/'ProphecY_Photo_UI_Gallery_RevA.html';output.write_text(page,encoding='utf-8')
print('created',output, 'size MiB',round(output.stat().st_size/1024/1024,2),'with',len(meta['dials']), 'dials and',len(meta['modules']),'modules')
